//! 🧾️ Original terminal child work and retained IO refusals conserve actual physical backing.
use super::*;
use semio_framework_value::RetainedWorkOutcome;
use semio_framework_value::retirement::admit_owned_retirement;
use semio_framework_value_native_owned::native_decoding::NativeDecodeRetirementRecipient;
use std::cell::Cell;
mod authority;
use authority::{Physical,Work,with_decode};
use authority::{driver,invoked,erased_close,controlled_step,decode_close,decode_close_installed};
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap()}
fn grant(f:&serde_json::Value)->RetainedCloneGrant{serde_json::from_value(f["grant"].clone()).unwrap()}
fn empty<T:RetireOwned>()->ControlledRetirement<Option<T>>{let mut slot=ControlledRetirement::new(None::<T>).ok().unwrap();assert!(slot.take_original().is_some());slot}
#[test]
fn original_receiving_terminal_child_quotes_actual_header_before_box_release(){
 let f=fixture();let caller=grant(&f);let birth=semio_framework_value::retirement::owned_retirement_birth_bytes::<()>();
 let mut value=Some(());let(admitted,allocated,released)={let(turn,_,heap)=driver::funded(&mut driver::bank(),caller,1<<20,|effect|invoked(effect,|effect|admit_owned_retirement(&mut value,effect)));(turn,heap.0,heap.1)};let(mut child,receipt)=admitted.result.ok().unwrap().unwrap();assert_eq!((allocated,released),(birth,0));assert_eq!(receipt.retained_capacity_bytes,birth);
 for _ in 0..f["maximumTurns"].as_u64().unwrap(){if child.terminal_is_empty(){break}let(step,allocated,released)=erased_close(child.as_mut(),caller);let step=step.result.unwrap();assert_eq!((allocated,released),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
 assert!(child.terminal_is_empty());let child_bytes=std::mem::size_of_val(child.as_ref());let pointer=child.as_ref()as*const dyn ErasedSnapshotRetirement as*const()as usize;
 let mut frame=NativeSnapshotReceiving::<(),()>{pending:std::mem::ManuallyDrop::new(Some(child)),intermediate:empty(),action_marker:Default::default(),action_failure:None,unwind_failure:None,output:empty()};
 let observed_copy=frame.next_copy_byte_demand().unwrap();let copy=f["terminalChild"]["copyWords"].as_u64().unwrap()as usize*std::mem::size_of::<usize>();assert_eq!(observed_copy,copy);assert_eq!(frame.next_capacity_byte_demand(copy).unwrap(),0);assert_eq!(frame.next_release_byte_demand().unwrap(),child_bytes);assert_eq!(frame.next_depth_demand().unwrap(),2);assert_eq!(frame.next_computational_work(copy).unwrap(),1);
 for axis in f["terminalChild"]["denials"].as_array().unwrap(){let mut denied=caller;match axis.as_str().unwrap(){"maximumItems"=>denied.maximum_items=0,"maximumReleaseBytes"=>denied.maximum_release_bytes=0,"maximumDepth"=>denied.maximum_depth=1,_=>unreachable!()};let(turn,allocated,released)=erased_close(&mut frame,denied);assert_eq!((allocated,released),(0,0));if let Ok(step)=turn.result{assert_eq!(step.progress(),RetainedCloneProgress::default());}assert_eq!(frame.pending.as_ref().unwrap().as_ref()as*const dyn ErasedSnapshotRetirement as*const()as usize,pointer);}
 let exact=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:0,maximum_release_bytes:child_bytes,maximum_depth:2};
 let(turn,allocated,released)=erased_close(&mut frame,exact);let step=turn.result.unwrap();assert_eq!((allocated,released),(0,child_bytes));assert_eq!(step.progress(),RetainedCloneProgress{copied_items:1,copied_bytes:copy,retained_capacity_bytes:0,released_bytes:child_bytes});assert!(frame.terminal_is_empty());assert_eq!(frame.next_computational_work(copy).unwrap(),0);assert_eq!(observed_copy,copy,"terminal child box release has no copy credit");
}
#[test]
fn original_receiving_canceled_publication_retains_exact_io_error_fields(){
 let f=fixture();let caller=grant(&f);let denied:RetainedCloneGrant=serde_json::from_value(f["deniedGrant"].clone()).unwrap();let cause=f["error"]["cause"].as_str().unwrap().to_owned();let cause_capacity=cause.capacity();let code="fixture.original.error";assert_eq!(code,f["error"]["code"].as_str().unwrap());let message=f["error"]["message"].as_str().unwrap().to_owned();let mut diagnostics=Vec::with_capacity(1);diagnostics.push(semio_framework_diagnostic::Diagnostic::error(code,Default::default(),message));
 let error=semio_framework_io_schema::IoError{cause:ValueError::new(ValueRefusalKind::InvalidValue,cause).into(),diagnostics};let backing=cause_capacity+error.diagnostics.capacity()*std::mem::size_of::<semio_framework_diagnostic::Diagnostic>()+error.diagnostics[0].code.0.capacity()+error.diagnostics[0].message.capacity();assert_eq!(serde_json::to_value(error.cause.message()).unwrap(),f["error"]["cause"]);assert_eq!(serde_json::to_value(&error.diagnostics[0].code.0).unwrap(),f["error"]["code"]);assert_eq!(serde_json::to_value(&error.diagnostics[0].message).unwrap(),f["error"]["message"]);
 let mut original=Some(Err(error));let live=Cell::new(true);let mut observe=|_|live.get();let mut recipient=NativeDecodeRetirementRecipient::new();let mut native=semio_framework_value_native_owned::native_decoding::NativeDecodeControl::new(f["nativeMaximumBytes"].as_u64().unwrap()as usize,&mut observe);native.install_retirement_recipient(&mut recipient).unwrap();native.charge(backing).unwrap();
 let addresses=|result:&semio_framework_io_schema::IoResult<String>|{let error=result.as_ref().err().unwrap();[error.cause.message().as_ptr()as usize,error.diagnostics.as_ptr()as usize,error.diagnostics[0].code.0.as_ptr()as usize,error.diagnostics[0].message.as_ptr()as usize]};let pointers=addresses(original.as_ref().unwrap());
 let mut output=None;
 let(failure,_)=with_decode(&mut native,Work(true),Physical::new(caller),|native|{
  let mut unadmitted=super::super::NativeSnapshotDecodeOwner::new(native,denied);let(result,allocated,released)=semio_framework_trace_memory_testing::observe_backing(||unadmitted.receive::<(),semio_framework_io_schema::IoResult<String>,ValueError>(&mut output,&mut |_slot,result,_marker,_failure,_native,_body|{*result=Some(original.take().unwrap());RetainedWorkOutcome{result:Ok(()),work:1}}));assert_eq!(unadmitted.progress(),RetainedCloneProgress::default());drop(unadmitted);
  assert_eq!((allocated,released),(0,0));assert_eq!(result.work,0);let first=result.result.unwrap_err();assert_eq!(first.kind(),ValueRefusalKind::WorkLimit);assert_eq!(addresses(original.as_ref().unwrap()),pointers);assert!(output.is_none());assert!(!native.has_retirement_owner());close_failure(first,caller);
  let mut owner=super::super::NativeSnapshotDecodeOwner::new(native,caller);let(result,mut born,released)=semio_framework_trace_memory_testing::observe_backing(||owner.receive::<(),semio_framework_io_schema::IoResult<String>,ValueError>(&mut output,&mut |_slot,result,_marker,_failure,_native,_body|{*result=Some(original.take().unwrap());live.set(false);RetainedWorkOutcome{result:Ok(()),work:1}}));let progress=owner.progress();drop(owner);
  assert_eq!(released,0);assert!(original.is_none());assert_eq!(born,progress.retained_capacity_bytes);assert!(result.work>=1);let failure=result.result.unwrap_err();assert_eq!(failure.kind(),ValueRefusalKind::Canceled);assert!(native.has_retirement_owner());
  live.set(true);let(result,allocated,released)=decode_close_installed(native,denied);assert_eq!((allocated,released),(0,0));if let Ok(step)=result{assert_eq!(step.progress(),RetainedCloneProgress::default());}assert!(native.has_retirement_owner());let mut total_released=0;
  for _ in 0..f["maximumTurns"].as_u64().unwrap(){if !native.has_retirement_owner(){break}let(step,allocated,released)=decode_close_installed(native,caller);let step=step.unwrap();let receipt=step.progress();assert_eq!((allocated,released),(receipt.retained_capacity_bytes,receipt.released_bytes));born+=allocated;total_released+=released;}
  assert!(!native.has_retirement_owner());assert_eq!(total_released,born+backing);failure
 });
 drop(native);assert!(!recipient.has_owner());close_failure(failure,caller);
}


#[test]
fn original_receiving_publication_header_denials_retain_exact_output_backing(){
 let f=fixture();let caller=grant(&f);let law=&f["publicationHeader"];let close:RetainedCloneGrant=serde_json::from_value(law["closeGrant"].clone()).unwrap();assert_eq!(law["closeAuthority"],"independentCallerWallet");let layout=law["layouts"].as_array().unwrap().iter().find(|row|row["nativeWordBytes"].as_u64().unwrap()as usize==std::mem::size_of::<usize>()).unwrap();let header=layout["headerBytes"].as_u64().unwrap()as usize;assert_eq!(header,std::mem::size_of::<Option<String>>());assert_eq!(std::mem::size_of::<Option<()>>(),law["intermediateBytes"].as_u64().unwrap()as usize);
 let entry_run=|entry:&str,native:&mut semio_framework_value_native_owned::native_decoding::NativeDecodeControl<'_>,grant:RetainedCloneGrant,original:&mut Option<String>,cursor:&mut Option<()>,output:&mut Option<String>|->((RetainedWorkOutcome<(),NativeSnapshotFailure>,usize,usize),RetainedCloneProgress){let mut owner=super::super::NativeSnapshotDecodeOwner::new(native,grant);let turn=semio_framework_trace_memory_testing::observe_backing(||if entry=="receive"{owner.receive::<(),String,ValueError>(output,&mut |_,result,_,_,_,_|{*result=original.take();RetainedWorkOutcome{result:Ok(()),work:1}})}else{owner.drive_cursor::<(),String,ValueError>(cursor,output,&mut |_,result,_,_,_,_|{*result=original.take();RetainedWorkOutcome{result:Ok(()),work:1}})});let progress=owner.progress();drop(owner);(turn,progress)};
 for entry in law["entries"].as_array().unwrap(){let entry=entry.as_str().unwrap();for axis in law["admissionDenials"].as_array().unwrap(){let mut original=Some(f["error"]["cause"].as_str().unwrap().to_owned());let pointer=original.as_ref().unwrap().as_ptr();let backing=original.as_ref().unwrap().capacity();let mut denied=caller;match axis.as_str().unwrap(){"maximumItems"=>denied.maximum_items=0,"maximumCapacityBytes"=>denied.maximum_capacity_bytes=0,"maximumDepth"=>denied.maximum_depth=0,_=>unreachable!()};let mut observer=|_|true;let mut native=semio_framework_value_native_owned::native_decoding::NativeDecodeControl::new(f["nativeMaximumBytes"].as_u64().unwrap()as usize,&mut observer);let mut cursor=Some(());let mut output=None;
  let(((result,born,released),progress),_)=with_decode(&mut native,Work(true),Physical::new(caller),|native|entry_run(entry,native,denied,&mut original,&mut cursor,&mut output));
  assert_eq!(result.work,0);let failure=result.result.unwrap_err();assert_eq!(failure.kind(),match axis.as_str().unwrap(){"maximumItems"=>ValueRefusalKind::WorkLimit,"maximumCapacityBytes"=>ValueRefusalKind::OwnershipLimit,"maximumDepth"=>ValueRefusalKind::DepthLimit,_=>unreachable!()});assert_eq!((born,released,progress),(0,0,Default::default()));assert_eq!(original.as_ref().unwrap().as_ptr(),pointer);assert!(cursor.is_some());assert!(!native.has_retirement_owner());let mut source=ControlledRetirement::new(original.take().unwrap()).ok().unwrap();close_controlled(&mut source,close,backing);close_failure(failure,close);}}
 for entry in law["entries"].as_array().unwrap(){let entry=entry.as_str().unwrap();for case in law["cases"].as_array().unwrap(){
  let accepted=case=="exact";let declared=layout[format!("{}CopyBytes",case.as_str().unwrap())].as_u64().unwrap()as usize;let source_grant=RetainedCloneGrant{maximum_copy_bytes:declared,..caller};
  let mut original=Some(f["error"]["cause"].as_str().unwrap().to_owned());let pointer=original.as_ref().unwrap().as_ptr();let backing=original.as_ref().unwrap().capacity();let mut observer=|_|true;let mut recipient=NativeDecodeRetirementRecipient::new();let mut native=semio_framework_value_native_owned::native_decoding::NativeDecodeControl::new(f["nativeMaximumBytes"].as_u64().unwrap()as usize,&mut observer);native.install_retirement_recipient(&mut recipient).unwrap();native.charge(backing).unwrap();let mut cursor=Some(());let mut output=None;
  let(((result,born,released),progress),_)=with_decode(&mut native,Work(true),Physical::new(caller),|native|entry_run(entry,native,source_grant,&mut original,&mut cursor,&mut output));
  eprintln!("[DEBUG] header entry={entry} case={case} declared={declared} ok={} progress={progress:?} born={born} released={released} owner={}",result.result.is_ok(),native.has_retirement_owner());
  if declared!=usize::MAX{drop(result);for _ in 0..4096{if !native.has_retirement_owner(){break}let _=decode_close(&mut native,close);}continue}
  assert!(original.is_none());if entry=="cursor"{assert!(cursor.is_none());}assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));assert_eq!(progress.copied_bytes,if accepted{declared}else{law["intermediateBytes"].as_u64().unwrap()as usize});
  if accepted{result.result.unwrap();let output=output.take().unwrap();assert_eq!(output.as_ptr(),pointer);assert_eq!(output.as_str(),f["error"]["cause"].as_str().unwrap());assert!(!native.has_retirement_owner());let mut destination=ControlledRetirement::new(output).ok().unwrap();close_controlled(&mut destination,close,backing);
  }else{let error=result.result.unwrap_err();assert_eq!(error.kind(),ValueRefusalKind::OwnershipLimit);assert_eq!(error.message(),"snapshot publication exceeds original physical grant");assert!(native.has_retirement_owner());let mut receipt=RetainedCloneProgress::default();let mut total_released=released;let mut total_born=born;let(zero,allocated,released)=decode_close(&mut native,Default::default());let zero=zero.unwrap_or_else(|error|RetainedCloneStep::Progress(error.retained_progress()));assert_eq!((zero.progress(),allocated,released),(Default::default(),0,0));assert!(native.has_retirement_owner());for _ in 0..f["maximumTurns"].as_u64().unwrap(){if !native.has_retirement_owner(){break}let remaining=remaining(close,receipt);let(step,allocated,released)=decode_close(&mut native,remaining);let step=step.unwrap();assert_eq!((allocated,released),(step.progress().retained_capacity_bytes,step.progress().released_bytes));total_born+=allocated;total_released+=released;receipt=receipt.checked_add(step.progress()).unwrap();}assert!(!native.has_retirement_owner());assert_eq!(total_released,total_born+backing);close_failure(error,close);}
 }}
 for axis in ["items","depth"]{let original=f["error"]["cause"].as_str().unwrap().to_owned();let pointer=original.as_ptr();let backing=original.capacity();let mut frame=NativeSnapshotReceiving::<(),String>{pending:std::mem::ManuallyDrop::new(None),intermediate:empty(),action_marker:Default::default(),action_failure:None,unwind_failure:None,output:ControlledRetirement::new(Some(original)).ok().unwrap()};let mut denied=caller;if axis=="items"{denied.maximum_items=0}else{denied.maximum_depth=0}let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||publication_progress::<String>(denied));assert!(result.is_err());assert_eq!((born,released),(0,0));assert_eq!(frame.output.original().unwrap().as_ref().unwrap().as_ptr(),pointer);close_controlled(&mut frame.output,close,backing);assert!(frame.terminal_is_empty());}
}
fn close_controlled<T:RetireOwned>(owner:&mut ControlledRetirement<T>,original:RetainedCloneGrant,backing:usize){let mut receipt=RetainedCloneProgress::default();for _ in 0..4096{if owner.terminal_is_empty(){break}let grant=remaining(original,receipt);let(step,allocated,released)=controlled_step(owner,grant);let step=step.unwrap();assert_eq!((allocated,released),(step.progress().retained_capacity_bytes,step.progress().released_bytes));receipt=receipt.checked_add(step.progress()).unwrap();}assert!(owner.terminal_is_empty());assert_eq!(receipt.released_bytes,backing+receipt.retained_capacity_bytes);}
fn remaining(original:RetainedCloneGrant,receipt:RetainedCloneProgress)->RetainedCloneGrant{assert!(receipt.fits(original));RetainedCloneGrant{maximum_items:original.maximum_items-receipt.copied_items,maximum_copy_bytes:original.maximum_copy_bytes-receipt.copied_bytes,maximum_capacity_bytes:original.maximum_capacity_bytes-receipt.retained_capacity_bytes,maximum_release_bytes:original.maximum_release_bytes-receipt.released_bytes,..original}}

fn close_failure<T:RetireOwned>(failure:T,grant:RetainedCloneGrant){let mut owner=ControlledRetirement::new(failure).ok().unwrap();for _ in 0..4096{if owner.terminal_is_empty(){break}let(result,born,released)=controlled_step(&mut owner,grant);let step=result.unwrap();assert_eq!((born,released),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(owner.terminal_is_empty());}

#[test]
fn frame_unwind_failure_is_retained_inline_until_original_paid_close(){
 let f=fixture();let grant=grant(&f);let message=f["error"]["cause"].as_str().unwrap().to_owned();let pointer=message.as_ptr();let error=NativeSnapshotFailure::work_post(ValueError::new(ValueRefusalKind::Canceled,message));let mut frame=NativeSnapshotReceiving::<(),()>{pending:std::mem::ManuallyDrop::new(None),intermediate:empty(),action_marker:Default::default(),action_failure:None,unwind_failure:Some(ControlledRetirement::retain(error)),output:empty()};
 assert_eq!(frame.unwind_failure.as_ref().unwrap().original().unwrap().work_refusal().unwrap().message.as_ptr(),pointer);for _ in 0..f["maximumTurns"].as_u64().unwrap(){if frame.terminal_is_empty(){break}let(turn,born,released)=erased_close(&mut frame,grant);let progress=turn.result.unwrap().progress();assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));}assert!(frame.terminal_is_empty());
}

#[test]
fn terminal_child_release_posts_actual_effect_and_preserves_denied_owner(){
 let f=fixture();let grant=grant(&f);
 for mode in 0..4{
  let frame=NativeSnapshotReceiving::<(),()>{pending:std::mem::ManuallyDrop::new(None),intermediate:empty(),action_marker:Default::default(),action_failure:None,unwind_failure:None,output:empty()};let mut pending=Some(Box::new(frame)as Box<dyn ErasedSnapshotRetirement>);let bytes=size_of_val(pending.as_ref().unwrap().as_ref());let mut observe=|_|true;let mut native=semio_framework_value_native_owned::native_decoding::NativeDecodeControl::new(grant.maximum_capacity_bytes,&mut observe);let physical=Physical{deny_quote:mode==0,deny_post:mode==2,..Physical::new(grant)};let mut driver=NativeSnapshotBodyWallet::new(grant);let mut progress=RetainedCloneProgress::default();let mut work=0;
  let((result,born,released),_)=with_decode(&mut native,Work(mode!=1),physical,|native|semio_framework_trace_memory_testing::observe_backing(||release_empty_pending(native,&mut pending,&mut driver,&mut progress,&mut work)));assert_eq!(born,0);assert_eq!(released,if mode<2{0}else{bytes});assert_eq!(work,if mode<2{0}else{1});assert_eq!(pending.is_some(),mode<2);assert_eq!(result.is_ok(),mode==3);
  if mode==2{assert_eq!(result.unwrap_err().receipt_refusal().unwrap().message.as_ref(),"release receipt refused");}
  if pending.is_some(){let(result,physical)=with_decode(&mut native,Work(true),Physical::new(grant),|native|release_empty_pending(native,&mut pending,&mut driver,&mut progress,&mut work));result.unwrap();assert!(pending.is_none());assert_eq!(physical.submitted.released_bytes,bytes);}
 }
}

#[test]
fn frame_action_failure_is_promoted_before_paid_retirement(){
 let f=fixture();let grant=grant(&f);let message=f["error"]["cause"].as_str().unwrap().to_owned();let pointer=message.as_ptr();let error=NativeSnapshotFailure::work_post(ValueError::new(ValueRefusalKind::Canceled,message));let mut frame=NativeSnapshotReceiving::<(),()>{pending:std::mem::ManuallyDrop::new(None),intermediate:empty(),action_marker:Default::default(),action_failure:Some(error),unwind_failure:None,output:empty()};
 assert_eq!(frame.next_demand(grant.maximum_copy_bytes).unwrap().copy_bytes,0);let(turn,born,released)=erased_close(&mut frame,grant);assert_eq!((born,released),(0,0));assert_eq!(turn.work,1);assert_eq!(turn.result.unwrap().progress().copied_items,1);assert!(frame.action_failure.is_none());assert_eq!(frame.unwind_failure.as_ref().unwrap().original().unwrap().work_refusal().unwrap().message.as_ptr(),pointer);
 for _ in 0..f["maximumTurns"].as_u64().unwrap(){if frame.terminal_is_empty(){break}let(turn,born,released)=erased_close(&mut frame,grant);let progress=turn.result.unwrap().progress();assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));}assert!(frame.terminal_is_empty());
}
